INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Domain Name System nur für Webseiten zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch E-Mail, andere Dienste"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat DNS?', 3, '[{"text": "IP-Adressen auflösen", "correct": true, "because": "Namen zu IPs"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht DNS-Aufgabe"}, {"text": "Netzwerkverkehr filtern", "correct": false, "because": "Firewall-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zum DNS?', 5, '[{"text": "Resolver", "correct": true, "because": "Fragen stellen"}, {"text": "Nameserver", "correct": true, "because": "Antworten liefern"}, {"text": "Router", "correct": false, "because": "Netzwerkgerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DNS übersetzt Domains in IPs. b) Es verschlüsselt Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von DNS?', 4, '[{"text": "Nameserver-Adresse", "correct": false, "because": "Notwendig"}, {"text": "Domainstruktur", "correct": false, "because": "Kern des Systems"}, {"text": "Routerfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DNS auf Port 53 läuft?', 2, '[{"text": "Ja", "correct": true, "because": "Standardport"}, {"text": "Nein", "correct": false, "because": "Port 53 genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll verwendet DNS standardmäßig?', 3, '[{"text": "UDP", "correct": true, "because": "Schnelle Abfragen"}, {"text": "TCP", "correct": false, "because": "Nur bei großen Antworten"}, {"text": "HTTP", "correct": false, "because": "Webprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben hat ein DNS-Server?', 5, '[{"text": "Domainnamen auflösen", "correct": true, "because": "IP-Adressen liefern"}, {"text": "Einträge speichern", "correct": true, "because": "DNS-Datenbank"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DNS ist hierarchisch. b) Es funktioniert ohne Internet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Internet nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DNS?', 4, '[{"text": "Nameserver", "correct": false, "because": "Antworten liefern"}, {"text": "Resolver", "correct": false, "because": "Abfragen stellen"}, {"text": "Physischer Server", "correct": true, "because": "Cloud möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DNS dasselbe wie DHCP?', 2, '[{"text": "Nein", "correct": true, "because": "DNS löst Namen, DHCP vergibt IPs"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einträge speichert DNS?', 4, '[{"text": "A-Record", "correct": true, "because": "IPv4-Adresse"}, {"text": "MX-Record", "correct": true, "because": "Mailserver"}, {"text": "HTTP-Header", "correct": false, "because": "Webprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DNS nur IPv4 unterstützt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IPv6 (AAAA)"}, {"text": "Ja", "correct": false, "because": "IPv6 wird unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der DNS-Konfiguration?', 3, '[{"text": "Verfügbarkeit", "correct": true, "because": "Schnelle Antworten"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DNS nutzt eine Hierarchie. b) Es ist ein Hardwareprotokoll.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Softwarebasiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DNS?', 5, '[{"text": "Einfache Namensnutzung", "correct": true, "because": "Domains statt IPs"}, {"text": "Schnelle Auflösung", "correct": true, "because": "Caching"}, {"text": "Physische Verbindung", "correct": false, "because": "Softwareebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DNS unwichtig?', 3, '[{"text": "TTL-Wert", "correct": false, "because": "Caching-Dauer"}, {"text": "Nameserver", "correct": false, "because": "Antwortquelle"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DNS lokal funktionieren?', 3, '[{"text": "Ja", "correct": true, "because": "Lokale Server möglich"}, {"text": "Nein", "correct": false, "because": "Nicht nur Internet"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DNS rekursiv arbeitet?', 2, '[{"text": "Ja", "correct": true, "because": "Resolver fragen weiter"}, {"text": "Nein", "correct": false, "because": "Rekursion üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für DNS zentral?', 4, '[{"text": "Hierarchisches System", "correct": true, "because": "Root, TLD, Domains"}, {"text": "Physische Kabel", "correct": false, "because": "Netzwerk"}, {"text": "Manuelle Zuweisung", "correct": false, "because": "Automatisiert"}]');
